INSERT INTO public.featured_promotions (id,kind,title,body,media_url,cta_label,cta_href,sort_order,is_active) VALUES ('promo-acto-3','STORY','Acto 3 · Repositorio Fantasma','Jaku ha desbloqueado el Acto 3. Enfréntate en el Repositorio Fantasma y descubre qué se esconde tras las puertas digitales.',NULL,'Ir a Story','/hub/story',1,TRUE), ('promo-chat','NEWS','Chat de Comunidad en Vivo','Comparte estrategias, reacciona con emojis y reta a duelo a otros jugadores en tiempo real. ¡Únete a la conversación!',NULL,'Abrir Chat','/hub/chat',2,TRUE), ('promo-motor-v2','NEWS','Motor Overworld v2','Nuevo motor de interacción: puertas, puentes y eventos que responden a tus acciones en el mapa. Más inmersión, más estrategia.',NULL,'Explorar','/hub/story',3,FALSE), ('promo-new-cards-live','CARD','Nuevas cartas ya disponibles','Flutter Enjambre, Escudo Firewall, Cubo Metálico, Octocat, TypeScript y muchas más: nuevas magias y trampas ya están en el mercado y en el evento de Fragmentos.','/assets/renders/traps/trap-flutter-reflect.webp','Ver Mercado','/hub/market',1,TRUE), ('promo-proximamente','CARD','Próximamente: Nuevas Cartas','Estamos preparando un nuevo lote de entities, trampas y efectos. ¡Estén atentos a las próximas actualizaciones!',NULL,'Ver Mercado','/hub/market',5,FALSE), ('promo-soldado-laptop','NEWS','Nuevo Oponente: Soldado-Laptop','Un nuevo rival patrulla la Arena. ¿Podrás derrotarlo y escalar en el ranking? Prepárate para un combate duro.',NULL,'Ir a Arena','/hub/multiplayer',4,TRUE), ('promo-top-semana','NEWS','Top Jugadores de la Semana','Consulta los mejores jugadores de la semana en el ranking. ¡Compite por la cima y gana reconocimiento!',NULL,'Ver Ranking','/hub/ranking',6,TRUE) ON CONFLICT (id) DO UPDATE SET kind=excluded.kind,title=excluded.title,body=excluded.body,media_url=excluded.media_url,cta_label=excluded.cta_label,cta_href=excluded.cta_href,sort_order=excluded.sort_order,is_active=excluded.is_active;

